const listAssignedTicketsAcrossWorkspaces = `-- name: ListAssignedTicketsAcrossWorkspaces :many
SELECT
  t.id,
  t.project_id,
  t.number,
  t.title,
  t.priority,
  t.due_date,
  t.created_at,
  w.slug AS workspace_slug,
  w.name AS workspace_name,
  p.key AS project_key,
  p.name AS project_name,
  s.name AS status_name,
  s.category AS status_category,
  s.color AS status_color,
  ty.name AS type_name
FROM tickets t
JOIN principals me
  ON me.workspace_id = t.workspace_id AND me.kind = 'user' AND me.user_id = $1
JOIN ticket_assignments a
  ON a.workspace_id = t.workspace_id AND a.ticket_id = t.id AND a.assignee_principal_id = me.id
JOIN workspaces w
  ON w.id = t.workspace_id
JOIN projects p
  ON p.id = t.project_id
JOIN ticket_statuses s
  ON s.workspace_id = t.workspace_id AND s.id = t.status_id
JOIN ticket_types ty
  ON ty.workspace_id = t.workspace_id AND ty.id = t.type_id
WHERE t.workspace_id IN (
    SELECT value::uuid FROM json_array_elements_text($2::json) AS v(value)
  )
  AND s.category <> 'done'
  AND t.archived_at IS NULL
  AND t.deleted_at IS NULL
ORDER BY t.due_date ASC NULLS LAST, t.created_at ASC, t.id ASC
LIMIT $3
`

type ListAssignedTicketsAcrossWorkspacesParams struct {
	UserID       sql.NullInt64
	WorkspaceIds json.RawMessage
	RowLimit     int32
}

type ListAssignedTicketsAcrossWorkspacesRow struct {
	ID             uuid.UUID
	ProjectID      uuid.UUID
	Number         int64
	Title          string
	Priority       int32
	DueDate        pgtext.NullDate
	CreatedAt      time.Time
	WorkspaceSlug  string
	WorkspaceName  string
	ProjectKey     string
	ProjectName    string
	StatusName     string
	StatusCategory string
	StatusColor    string
	TypeName       string
}

// ホームの「自分の担当」。全ワークスペースを横断し、未完了のものを期限の近い順に上限まで返す。
//
// ListAssignedTicketsForPrincipal（1 ワークスペースの全件）との違いは 4 つ。
//  1. 対象のワークスペースは呼び出し側が渡す（workspace_ids）。usecase が所属一覧を domain の
//     判定にかけ、チケットを見てよいワークスペースだけに絞ってから渡す。ここでは所属も役割も
//     判定しない（判定を SQL と domain の 2 か所に置かない）。上限は、絞った後の行にかかる。
//  2. 自分の principal はワークスペースごとに別の行なので、principals（kind='user'・user_id）と
//     JOIN して「そのワークスペースでの自分」を解く。workspace_ids にあっても自分の principal が
//     無いワークスペース（判定の後に所属を外れた等）の行は、この JOIN で 1 件も出ない。
//  3. 完了（状態の枠が done）を除き、期限の近い順 → 期限なしは最後 → 作成の古い順 → id の順に
//     並べてから切る。最後の id は、期限も作成時刻も同じ行の順を毎回同じにするため（上限で切る
//     一覧は、順が揺れると境目の行が出たり消えたりする）。緊急度や重要度は推測しない。
//  4. 一覧の 1 行に要る列だけを返す（本文の doc / plain_text は返さない）。
func (q *Queries) ListAssignedTicketsAcrossWorkspaces(ctx context.Context, arg ListAssignedTicketsAcrossWorkspacesParams) ([]ListAssignedTicketsAcrossWorkspacesRow, error) {
	rows, err := q.db.QueryContext(ctx, listAssignedTicketsAcrossWorkspaces, arg.UserID, arg.WorkspaceIds, arg.RowLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListAssignedTicketsAcrossWorkspacesRow{}
	for rows.Next() {
		var i ListAssignedTicketsAcrossWorkspacesRow
		if err := rows.Scan(
			&i.ID,
			&i.ProjectID,
			&i.Number,
			&i.Title,
			&i.Priority,
			&i.DueDate,
			&i.CreatedAt,
			&i.WorkspaceSlug,
			&i.WorkspaceName,
			&i.ProjectKey,
			&i.ProjectName,
			&i.StatusName,
			&i.StatusCategory,
			&i.StatusColor,
			&i.TypeName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

