const upsertTicketAssignment = `-- name: UpsertTicketAssignment :one

INSERT INTO ticket_assignments
  (workspace_id, ticket_id, assignee_principal_id, assigned_by_user_id, created_at)
VALUES ($1, $2, $3, $4, now())
ON CONFLICT (ticket_id)
DO UPDATE SET assignee_principal_id = EXCLUDED.assignee_principal_id,
              assigned_by_user_id = EXCLUDED.assigned_by_user_id
WHERE ticket_assignments.workspace_id = EXCLUDED.workspace_id
RETURNING workspace_id, ticket_id, assignee_principal_id, assignee_kind, assigned_by_user_id, created_at, deleted_at
`

type UpsertTicketAssignmentParams struct {
	WorkspaceID         uuid.UUID
	TicketID            uuid.UUID
	AssigneePrincipalID uuid.UUID
	AssignedByUserID    int64
}

// =============================================================================
// ticket_assignments
// =============================================================================
// 衝突キー (ticket_id) は PK 単独だが、行の所有者列 workspace_id が EXCLUDED と一致する
// ときだけ更新する（blocks の upsert と同じ形。呼び出し側が ticket_id と workspace_id を
// 取り違えても、他テナントの行を上書きしない歯止めになる）。
func (q *Queries) UpsertTicketAssignment(ctx context.Context, arg UpsertTicketAssignmentParams) (TicketAssignment, error) {
	row := q.db.QueryRowContext(ctx, upsertTicketAssignment,
		arg.WorkspaceID,
		arg.TicketID,
		arg.AssigneePrincipalID,
		arg.AssignedByUserID,
	)
	var i TicketAssignment
	err := row.Scan(
		&i.WorkspaceID,
		&i.TicketID,
		&i.AssigneePrincipalID,
		&i.AssigneeKind,
		&i.AssignedByUserID,
		&i.CreatedAt,
		&i.DeletedAt,
	)
	return i, err
}

const upsertTicketBacklogRank = `-- name: UpsertTicketBacklogRank :exec
INSERT INTO ticket_backlog_ranks (workspace_id, project_id, ticket_id, "position", created_at, updated_at)
VALUES ($1, $2, $3, $4, now(), now())
ON CONFLICT (workspace_id, ticket_id)
DO UPDATE SET "position" = EXCLUDED."position", updated_at = now()
`

type UpsertTicketBacklogRankParams struct {
	WorkspaceID uuid.UUID
	ProjectID   uuid.UUID
	TicketID    uuid.UUID
	Position    string
}

// 復元（アーカイブ解除・削除取り消し）で末尾へ置き直すときに使う。
//
// 素の UPDATE ではなく upsert にしてあるのは、並び順の行が無いチケットが有り得るため
// —— この表より前に作られたチケットは、移行で現役の分だけに行を入れた（撤去済みだった
// tickets.position から写した）。当時アーカイブ済み・削除済みだった分には行が無い。
// UPDATE だけだと、そういうチケットを復元したときに 0 行で失敗する。
func (q *Queries) UpsertTicketBacklogRank(ctx context.Context, arg UpsertTicketBacklogRankParams) error {
	_, err := q.db.ExecContext(ctx, upsertTicketBacklogRank,
		arg.WorkspaceID,
		arg.ProjectID,
		arg.TicketID,
		arg.Position,
	)
	return err
}
